diff --git a/tests/cases/fourslash/quickInfoMappedTypeOverAssertionTypeReuse.ts b/tests/cases/fourslash/quickInfoMappedTypeOverAssertionTypeReuse.ts
new file mode 100644
index 000000000..f05ae0cc9
--- /dev/null
+++ b/tests/cases/fourslash/quickInfoMappedTypeOverAssertionTypeReuse.ts
@@ -0,0 +1,36 @@
+/// <reference path="fourslash.ts" />
+
+// @strict: true
+
+//// type Wrapper<T> = {
+////     _type: T
+//// }
+////
+//// function stringWrapper(): Wrapper<string> {
+////     return { _type: "" }
+//// }
+////
+//// function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+////     return { _type: obj }
+//// }
+////
+//// const value = objWrapper({
+////     prop1: stringWrapper() as Wrapper<"hello">
+//// })
+////
+//// type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+////     ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+////     : T['_type']
+////
+//// type /*1*/Test = Unwrap<typeof value>
+//// type /*2*/Test2 = Unwrap<typeof value>["prop1"]
+////
+//// const strWrapper = stringWrapper() as Wrapper<"hello">;
+//// const value2 = objWrapper({
+////     prop1: strWrapper
+//// })
+//// type /*3*/Test3 = Unwrap<typeof value2>
+
+verify.quickInfoAt("2", 'type Test2 = "hello"');
+verify.quickInfoAt("3", 'type Test3 = {\n    prop1: "hello";\n}');
+verify.quickInfoAt("1", 'type Test = {\n    prop1: "hello";\n}');
